{"output":"import React, { useState, useEffect } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from '@/shadcn/ui/card'
import { Badge } from '@/shadcn/ui/badge'
import { Button } from '@/shadcn/ui/button'
import { 
  Server, 
  Layers, 
  Play, 
  Coins, 
  AlertTriangle, 
  BookOpen,
  RefreshCw
} from 'lucide-react'
import { get } from '@/lib/api'

interface Feature {
  id: number
  title: string
  status: string
}

interface Task {
  id: number
  feature_id: number
  role: string
  status: string
}

interface GraphRun {
  run_id: string
  feature_id: number
  status: string
  last_checkpoint_at: string
}

interface TokenStats {
  role: string
  model: string
  total_tokens: number
  daily_limit: number
  daily_used: number
}

interface LogEntry {
  ts: string
  level: string
  component: string
  event: string
}

interface DocSummary {
  total: number
  updatedToday: number
}

const Dashboard: React.FC = () => {
  const [features, setFeatures] = useState<Feature[]>([])
  const [tasks, setTasks] = useState<Task[]>([])
  const [runs, setRuns] = useState<GraphRun[]>([])
  const [tokenStats, setTokenStats] = useState<TokenStats[]>([])
  const [logs, setLogs] = useState<LogEntry[]>([])
  const [docsSummary, setDocsSummary] = useState<DocSummary>({ total: 0, updatedToday: 0 })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchData = async () => {
    setLoading(true)
    try {
      const [featuresRes, tasksRes, runsRes, tokensRes, logsRes] = await Promise.allSettled([
        get<Feature[]>('/orchestrator/features'),
        get<Task[]>('/orchestrator/tasks'),
        get<GraphRun[]>('/orchestrator/runs'),
        get<TokenStats[]>('/admin/tokens/stats'),
        get<LogEntry[]>('/logs/tail?limit=5'),
      ])

      if (featuresRes.status === 'fulfilled') {
        setFeatures(featuresRes.value.data)
      } else {
        console.error('Dashboard: features fetch failed', featuresRes.reason)
      }

      if (tasksRes.status === 'fulfilled') {
        setTasks(tasksRes.value.data)
      } else {
        console.warn('Dashboard: tasks fetch failed', tasksRes.reason)
      }

      if (runsRes.status === 'fulfilled') {
        setRuns(runsRes.value.data)
      } else {
        console.warn('Dashboard: runs fetch failed', runsRes.reason)
      }

      if (tokensRes.status === 'fulfilled') {
        setTokenStats(tokensRes.value.data)
      } else {
        // Не считаем это критической ошибкой — просто скрываем/обнуляем бюджет
        console.warn('Dashboard: token stats fetch failed (non-blocking)', tokensRes.reason)
        setTokenStats([])
      }

      if (logsRes.status === 'fulfilled') {
        setLogs(logsRes.value.data)
      } else {
        console.warn('Dashboard: logs fetch failed (non-blocking)', logsRes.reason)
        setLogs([])
      }

      // Симулируем данные для документов (в реальной реализации будет API endpoint)
      setDocsSummary({ total: 42, updatedToday: 3 })

      // Ошибкой считаем только падение базовых источников для вёрстки
      if (featuresRes.status === 'rejected' && runsRes.status === 'rejected') {
        setError('Failed to fetch core data')
      } else {
        setError(null)
      }
    } catch (err) {
      console.error('Dashboard: unexpected fetch error', err)
      setError('Failed to fetch data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchData()
    // Обновляем данные каждые 5 секунд
    const interval = setInterval(fetchData, 5000)
    return () => clearInterval(interval)
  }, [])

  // Вычисляем статистику backlog
  const backlogStats = {
    new: features.filter(f => f.status === 'NEW').length,
    planned: features.filter(f => f.status === 'PLANNED').length,
    running: features.filter(f => f.status === 'RUNNING').length
  }

  // Вычисляем статистику бюджета токенов
  const budgetStats = tokenStats.reduce((acc, stat) => {
    acc.daily += stat.daily_limit
    acc.used += stat.daily_used
    return acc
  }, { daily: 0, used: 0, remaining: 0 })

